(function(){
'use strict';
function closePreview(){var m=document.getElementById('workspacePreviewModal');if(m)m.hidden=true;document.body.classList.remove('workspace-preview-open')}
function ensureModal(){var m=document.getElementById('workspacePreviewModal');if(m)return m;m=document.createElement('div');m.id='workspacePreviewModal';m.className='workspace-preview-modal';m.hidden=true;m.innerHTML='<button class="workspace-preview-backdrop" type="button" aria-label="미리보기 닫기"></button><section class="workspace-preview-dialog"><header><div><small>PREVIEW</small><b>작업화면 미리보기</b></div><button type="button" data-workspace-preview-close>×</button></header><div class="workspace-preview-viewport"><div class="workspace-preview-holder"></div></div></section>';document.body.appendChild(m);m.querySelector('.workspace-preview-backdrop').onclick=closePreview;m.querySelector('[data-workspace-preview-close]').onclick=closePreview;return m}
function openPreview(){var sheet=document.getElementById('sheet');if(!sheet)return;var m=ensureModal(),holder=m.querySelector('.workspace-preview-holder'),vw=m.querySelector('.workspace-preview-viewport');holder.innerHTML='';var clone=sheet.cloneNode(true),rect=sheet.getBoundingClientRect(),cs=getComputedStyle(sheet),baseW=sheet.offsetWidth||parseFloat(cs.width)||rect.width,baseH=sheet.scrollHeight||sheet.offsetHeight||rect.height;clone.removeAttribute('id');clone.classList.add('workspace-preview-sheet');clone.style.setProperty('width',baseW+'px','important');clone.style.setProperty('min-width',baseW+'px','important');clone.style.setProperty('max-width','none','important');clone.style.setProperty('height',baseH+'px','important');clone.style.setProperty('min-height',baseH+'px','important');clone.style.setProperty('margin','0','important');clone.style.setProperty('transform','none','important');clone.style.setProperty('transform-origin','top left','important');holder.appendChild(clone);m.hidden=false;document.body.classList.add('workspace-preview-open');requestAnimationFrame(function(){requestAnimationFrame(function(){var style=getComputedStyle(vw),padX=parseFloat(style.paddingLeft||0)+parseFloat(style.paddingRight||0),padY=parseFloat(style.paddingTop||0)+parseFloat(style.paddingBottom||0),availW=Math.max(100,vw.clientWidth-padX),availH=Math.max(100,vw.clientHeight-padY),scale=Math.min(availW/baseW,availH/baseH,1);clone.style.setProperty('transform','scale('+scale+')','important');clone.style.setProperty('transform-origin','top left','important');holder.style.width=(baseW*scale)+'px';holder.style.minWidth=(baseW*scale)+'px';holder.style.height=(baseH*scale)+'px';holder.style.minHeight=(baseH*scale)+'px';vw.scrollTop=0;vw.scrollLeft=0;})})}
function replaceButton(){var old=document.getElementById('previewBtn');if(!old)return;var b=old.cloneNode(true);b.dataset.workspacePreviewReady='2';old.replaceWith(b);b.addEventListener('click',function(e){e.preventDefault();e.stopImmediatePropagation();openPreview()},true)}
function init(){replaceButton()}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();setTimeout(init,100);
})();